import{_ as a,I as t,g as o,j as r}from"./chunks/framework.Ha9mtr6N.js";const h=JSON.parse('{"title":"Backups & Data Security","description":"Automatic GFS backups, manual export to ZIP/CSV, data recovery, and WAL protection against power failures.","frontmatter":{"title":"Backups & Data Security","description":"Automatic GFS backups, manual export to ZIP/CSV, data recovery, and WAL protection against power failures.","order":17},"headers":[],"relativePath":"docs/backups.md","filePath":"docs/backups.md"}'),i={name:"docs/backups.md"};function s(n,e,c,l,u,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation Under Development</p><p><strong>Dear Users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, with regular updates and expansions, the reference materials are also being updated gradually.</p><p>At this time, please treat the documentation as a guide—it is currently incomplete, may temporarily lack descriptions for certain features, or contain minor inaccuracies.</p></div><h1 id="🛡️-backups-data-security" tabindex="-1">🛡️ Backups &amp; Data Security <a class="header-anchor" href="#🛡️-backups-data-security" aria-label="Permalink to &quot;🛡️ Backups &amp; Data Security&quot;">​</a></h1><p>OmniCraft ERP is a local desktop application. We do not use cloud servers to store your financial operations, which ensures complete privacy and independence from the internet.</p><p>However, this also means that the physical safety of your database relies on your local computer. To protect your business from hard drive failures, accidental deletions, or ransomware, a multi-tiered automatic and manual backup system is built directly into the program.</p><hr><h2 id="🔄-automatic-shadow-copies-gfs-backups" tabindex="-1">🔄 Automatic Shadow Copies (GFS Backups) <a class="header-anchor" href="#🔄-automatic-shadow-copies-gfs-backups" aria-label="Permalink to &quot;🔄 Automatic Shadow Copies (GFS Backups)&quot;">​</a></h2><p>The program operates using a professional IT strategy: <strong>GFS (Grandfather-Father-Son)</strong>. The background system creates isolated database snapshots without blocking your work or causing any interface lag.</p><h3 id="_1-on-application-startup-startup-backups" tabindex="-1">1. On Application Startup (Startup Backups) <a class="header-anchor" href="#_1-on-application-startup-startup-backups" aria-label="Permalink to &quot;1. On Application Startup (Startup Backups)&quot;">​</a></h3><p>Every time you open OmniCraft ERP, the system checks the system time and creates a shadow copy if a new reporting period has arrived:</p><ul><li>📅 <strong>Daily Backup</strong> (<code>auto_daily.db</code>) — updated once a day.</li><li>🗓️ <strong>Weekly Backup</strong> (<code>auto_weekly.db</code>) — updated once a week.</li><li>🗓️ <strong>Monthly Backup</strong> (<code>auto_monthly.db</code>) — updated once a month.</li><li>🗓️ <strong>Yearly Backup</strong> (<code>auto_yearly.db</code>) — updated once a year.</li></ul><h3 id="_2-on-application-exit-close-backups" tabindex="-1">2. On Application Exit (Close Backups) <a class="header-anchor" href="#_2-on-application-exit-close-backups" aria-label="Permalink to &quot;2. On Application Exit (Close Backups)&quot;">​</a></h3><p>When you close the application, OmniCraft ERP performs two essential tasks:</p><ol><li><strong>Database Optimization:</strong> It executes SQLite system commands <code>PRAGMA optimize</code> and <code>VACUUM</code>. These compress the database file on your drive, reclaim &quot;empty space&quot; left by deleted records, and speed up future queries.</li><li><strong>Rotational Backups:</strong> It maintains a chain of three rotational slots (<code>auto_close_1.db</code>, <code>auto_close_2.db</code>, <code>auto_close_3.db</code>). Each time the application exits, the new backup pushes the previous ones back by one slot, giving you access to the last three exit states.</li></ol><h3 id="_3-safety-nets" tabindex="-1">3. Safety Nets <a class="header-anchor" href="#_3-safety-nets" aria-label="Permalink to &quot;3. Safety Nets&quot;">​</a></h3><p>Before executing any irreversible or potentially destructive actions, the program <strong>automatically</strong> takes a shadow backup:</p><ul><li>Before an &quot;Accounting Reset&quot; (wiping transaction history).</li><li>Before a &quot;Factory Reset&quot;.</li><li>Before automatic database migrations during application updates.</li></ul><div class="tip custom-block"><p class="custom-block-title">Where are automatic backups stored?</p><p>All automatic backups are located in the application&#39;s secure system directory (<code>AppData/Roaming/OmniCraft ERP/backups/</code> on Windows or <code>~/.config/OmniCraft ERP/backups/</code> on macOS/Linux). You can copy them to a USB drive or cloud storage at any time.</p></div><hr><h2 id="📦-manual-data-export-file-menu" tabindex="-1">📦 Manual Data Export (File Menu) <a class="header-anchor" href="#📦-manual-data-export-file-menu" aria-label="Permalink to &quot;📦 Manual Data Export (File Menu)&quot;">​</a></h2><p>To create archives that can be emailed, uploaded to cloud storage, or transferred to another computer, use the <strong>File ➔ Export Data</strong> menu. The program offers two formats:</p><h3 id="_1-binary-backup-db" tabindex="-1">1. Binary Backup (.db) <a class="header-anchor" href="#_1-binary-backup-db" aria-label="Permalink to &quot;1. Binary Backup (.db)&quot;">​</a></h3><p>Creates an exact 1:1 copy of your current database file.</p><ul><li><strong>How it works:</strong> It uses the native SQLite <code>.backup()</code> API, which safely copies data on the fly, even if the program is processing a sale at that exact millisecond.</li><li><strong>What it&#39;s for:</strong> Fast daily backups to an external drive or flash card.</li></ul><h3 id="_2-spreadsheet-archive-zip-with-csv" tabindex="-1">2. Spreadsheet Archive (.zip with CSV) <a class="header-anchor" href="#_2-spreadsheet-archive-zip-with-csv" aria-label="Permalink to &quot;2. Spreadsheet Archive (.zip with CSV)&quot;">​</a></h3><p>An advanced export that dumps <strong>absolutely all</strong> system tables (stock, receipts, recipes, settings) into separate text files (<code>.csv</code>) and packages them into a single <code>.zip</code> archive.</p><ul><li><strong>What it&#39;s for:</strong> This is your &quot;digital parachute.&quot; If your binary <code>.db</code> file ever suffers corruption due to filesystem failures and fails to load, you can always rebuild your entire history from these CSV spreadsheets. Furthermore, these files can be easily opened in Excel or Google Sheets for external audits.</li></ul><div class="info custom-block"><p class="custom-block-title">Global Export in PRO Mode</p><p>If you are using the PRO version with Multi-Workspaces, the manual export will package <strong>your entire ecosystem</strong> into a single ZIP archive: the <code>workspaces.json</code> registry, your personal finance database (<code>personal_finance.db</code>), and all business workspaces you have created.</p></div><hr><h2 id="⏳-data-recovery-import" tabindex="-1">⏳ Data Recovery (Import) <a class="header-anchor" href="#⏳-data-recovery-import" aria-label="Permalink to &quot;⏳ Data Recovery (Import)&quot;">​</a></h2><p>In the event of a computer crash, when moving the program to a new PC, or if you simply want to &quot;roll back&quot; to yesterday&#39;s state, use the <strong>File ➔ Import Data</strong> menu.</p><h3 id="restore-from-automatic-backup-time-machine" tabindex="-1">Restore from Automatic Backup (Time Machine) <a class="header-anchor" href="#restore-from-automatic-backup-time-machine" aria-label="Permalink to &quot;Restore from Automatic Backup (Time Machine)&quot;">​</a></h3><p>Select this option to open a list of all automatic GFS backups. The program will display clear cards with dates and the size of each snapshot (e.g., <em>“Daily Backup (Yesterday | 4.2 MB)”</em>).</p><ul><li>Select your preferred point in time.</li><li>Confirm the action. The program will completely overwrite the current database with the selected snapshot and <strong>automatically reboot</strong>.</li></ul><h3 id="restore-from-a-file-db-or-zip" tabindex="-1">Restore from a File (.db or .zip) <a class="header-anchor" href="#restore-from-a-file-db-or-zip" aria-label="Permalink to &quot;Restore from a File (.db or .zip)&quot;">​</a></h3><ul><li><strong>From a Binary Backup (.db):</strong> Completely replaces your current database with the file you select.</li><li><strong>From a CSV Archive (.zip):</strong> The program unpacks the archive, clears current database tables, and safely, line-by-line, restores your data. A built-in strict validator protects against SQL injection and accidental loading of corrupt files.</li></ul><div class="danger custom-block"><p class="custom-block-title">Warning: Full Overwrite</p><p>The import process <strong>does not merge</strong> data; instead, it completely replaces the current state of the application with the state saved in the backup file. Any receipts, purchases, or settings configured <em>after</em> the backup was created will be permanently lost. Always create a fresh export before restoring an old backup!</p></div><hr><h2 id="⚙️-under-the-hood-power-failure-protection-wal" tabindex="-1">⚙️ Under the Hood: Power Failure Protection (WAL) <a class="header-anchor" href="#⚙️-under-the-hood-power-failure-protection-wal" aria-label="Permalink to &quot;⚙️ Under the Hood: Power Failure Protection (WAL)&quot;">​</a></h2><p>In addition to backups, the OmniCraft ERP database architecture itself is engineered to survive extreme conditions.</p><p>The program utilizes <strong>WAL (Write-Ahead Logging)</strong> journal mode. Unlike standard databases that can suffer irreparable corruption if a power failure occurs while writing a transaction, WAL mode works differently:</p><ol><li>Any change is first written to a dedicated &quot;journal&quot; (WAL file).</li><li>Only after a successful write to the journal is the data safely committed to the main database.</li><li>If the power blinks or the system freezes, upon next startup, SQLite automatically reads the journal and <strong>rolls back</strong> any incomplete transactions.</li></ol><p>The database remains structurally integral, and your financial history won&#39;t turn into a corrupted mess. The maximum you might lose is the very last transaction that was in progress during the failure.</p><hr><h2 id="🧠-core-rules-of-safety" tabindex="-1">🧠 Core Rules of Safety <a class="header-anchor" href="#🧠-core-rules-of-safety" aria-label="Permalink to &quot;🧠 Core Rules of Safety&quot;">​</a></h2><p>To ensure your business data is secure, develop these simple habits:</p><ol><li><strong>The 3-2-1 Rule:</strong> Keep <strong>3</strong> copies of your data, on <strong>2</strong> different types of media (such as your PC and an external HDD), and <strong>1</strong> copy in the cloud (Dropbox, Google Drive, OneDrive, iCloud, Yandex.Disk, etc.).</li><li><strong>Weekly Manual Exports:</strong> Once a week, go to <code>File ➔ Export Data ➔ Spreadsheet Archive (.zip)</code> and upload the archive to your personal cloud or email.</li><li><strong>Do Not Ignore Updates:</strong> When new versions of OmniCraft ERP are released, the built-in migration system automatically adapts your database schema to new features, making a protective backup (<code>auto_before_scale_migration.db</code>) beforehand.</li></ol>',46)])])}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
